#!/usr/bin/env node
// One-shot dev script: captures the first [surah, ayah] of every one of the 240
// rub' al-hizb from the Quran.com Foundation API v4 and writes the checked-in
// src/lib/rub-el-hizb-starts.ts (the offline RUB_EL_HIZB_STARTS table). Mirrors
// fetch-page-starts.mjs: fetch, validate shape and structure, throw on any
// mismatch, write a checked-in generated file.
//
// Run manually (this environment blocks plain node fetch; --use-system-ca fixes
// it, same as the mushaf SSG build):
//   NODE_OPTIONS=--use-system-ca node scripts/fetch-rub-el-hizb-starts.mjs
//
// This script is NOT part of the build. RUB_EL_HIZB_STARTS is verified
// structural pagination captured once and committed; navigation.test.ts guards
// it against drift. Never hand-author the 240 verseKeys — that violates the
// binding content-verification rule (they are verified references from the API).

import { readFile, writeFile } from "node:fs/promises";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(__dirname, "..");
const INDEX_PATH = join(REPO_ROOT, "src", "data", "content", "surah-index.json");
const OUT_PATH = join(REPO_ROOT, "src", "lib", "rub-el-hizb-starts.ts");
const API_BASE = "https://api.quran.com/api/v4/verses/by_rub";

const TOTAL_RUB = 240;
const TOTAL_VERSES = 6236;

// Fetch one rub's first verse_key with a small retry, mirroring quran-api's
// fetchWithRetry policy (4xx fails fast; 5xx / network errors retry).
async function fetchRubStart(rub, retries = 3) {
  const url = `${API_BASE}/${rub}?per_page=1&fields=verse_key`;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const res = await fetch(url, { headers: { Accept: "application/json" } });
      if (res.status >= 400 && res.status < 500) {
        throw new Error(`rub ${rub}: ${res.status} ${res.statusText} (no retry)`);
      }
      if (!res.ok) throw new Error(`rub ${rub}: ${res.status} ${res.statusText}`);
      const json = await res.json();
      const key = json?.verses?.[0]?.verse_key;
      if (typeof key !== "string" || !/^\d{1,3}:\d{1,3}$/.test(key)) {
        throw new Error(`rub ${rub}: unexpected /verses/by_rub shape (missing verses[0].verse_key)`);
      }
      const [surah, ayah] = key.split(":").map(Number);
      return [surah, ayah];
    } catch (err) {
      if (attempt === retries || /no retry/.test(String(err))) throw err;
      await new Promise((r) => setTimeout(r, 400 * 2 ** attempt));
    }
  }
  throw new Error(`rub ${rub}: exhausted retries`);
}

// Fail-fast structural validation, mirroring the chapters.length !== 114 guard
// in fetch-surah-names.mjs. Refuses to write on any mismatch.
function validate(rubStarts, ayahCount) {
  if (rubStarts.length !== TOTAL_RUB) {
    throw new Error(`expected ${TOTAL_RUB} rub starts, captured ${rubStarts.length}`);
  }
  const [firstS, firstA] = rubStarts[0];
  if (firstS !== 1 || firstA !== 1) {
    throw new Error(`rub 1 must start at 1:1, captured ${firstS}:${firstA}`);
  }
  // Strictly monotonic by (surah, ayah): each rub starts at a new, later verse.
  for (let i = 1; i < rubStarts.length; i++) {
    const [s, a] = rubStarts[i];
    const [ps, pa] = rubStarts[i - 1];
    if (!(s > ps || (s === ps && a > pa))) {
      throw new Error(`rub ${i + 1} start ${s}:${a} is not after rub ${i} start ${ps}:${pa}`);
    }
  }
  // Every start ayah is within its surah's real ayah count.
  for (let i = 0; i < rubStarts.length; i++) {
    const [s, a] = rubStarts[i];
    const count = ayahCount.get(s);
    if (!count || a < 1 || a > count) {
      throw new Error(`rub ${i + 1} start ${s}:${a} is out of surah ${s}'s range (1..${count ?? 0})`);
    }
  }
  // Rub-by-rub walk: from each rub's start to the next rub's start (exclusive),
  // honoring each surah's real ayah count for rollover, must enumerate exactly
  // 6236 verses ending at 114:6 (same guard shape as the JUZ_STARTS enumeration).
  let total = 0;
  let lastKey = null;
  for (let r = 1; r <= TOTAL_RUB; r++) {
    const [startS, startA] = rubStarts[r - 1];
    const [endS, endA] = r < TOTAL_RUB ? rubStarts[r] : [115, 1]; // sentinel past 114:6
    let s = startS;
    let a = startA;
    while (s < endS || (s === endS && a < endA)) {
      total++;
      lastKey = `${s}:${a}`;
      a++;
      if (a > ayahCount.get(s)) {
        s++;
        a = 1;
      }
    }
  }
  if (total !== TOTAL_VERSES) {
    throw new Error(`rub walk enumerated ${total} verses, expected ${TOTAL_VERSES}`);
  }
  if (lastKey !== "114:6") {
    throw new Error(`rub walk ended at ${lastKey}, expected 114:6`);
  }
}

function render(rubStarts) {
  const header = `// GENERATED by scripts/fetch-rub-el-hizb-starts.mjs — DO NOT EDIT by hand.
// The first [surah, ayah] of each of the 240 rub' al-hizb of the standard Hafs
// 'an 'Asim mushaf (60 hizb x 4 rub'). Verified structural pagination (the same
// in every printing), captured once from
// api.quran.com/api/v4/verses/by_rub/{1..240} and cross-checked by enumeration
// to total exactly 6236 verses with no gaps or duplicates (rub' 240 is hizb 60
// and runs to 114:6). These are verseKey REFERENCES, not generated content — the
// same justification PAGE_STARTS / JUZ_STARTS carry. Re-run the generator after
// the pagination reference changes; navigation.test.ts is the drift guard.
// RUB_EL_HIZB_STARTS[n - 1] = first verse of rub' n; hizb n spans rub' 4n-3..4n.
`;
  const lines = rubStarts
    .map(([s, a], i) => `  [${s}, ${a}], // rub' ${i + 1}`)
    .join("\n");
  return `${header}export const RUB_EL_HIZB_STARTS: ReadonlyArray<readonly [number, number]> = [\n${lines}\n];\n`;
}

async function main() {
  const raw = await readFile(INDEX_PATH, "utf8");
  const index = JSON.parse(raw);
  if (!Array.isArray(index) || index.length !== 114) {
    throw new Error(`surah-index.json must hold 114 surahs, found ${Array.isArray(index) ? index.length : "non-array"}`);
  }
  const ayahCount = new Map(index.map((s) => [s.number, s.versesCount]));

  console.log(`Fetching first verse_key of rub' 1..${TOTAL_RUB} from Quran.com API v4...`);
  const rubStarts = [];
  for (let r = 1; r <= TOTAL_RUB; r++) {
    rubStarts.push(await fetchRubStart(r));
    if (r % 40 === 0 || r === TOTAL_RUB) console.log(`  ...captured ${r}/${TOTAL_RUB}`);
  }

  console.log("Validating captured table (240 / monotonic / in-range / 6236-walk ending 114:6)...");
  validate(rubStarts, ayahCount);

  await writeFile(OUT_PATH, render(rubStarts), "utf8");
  console.log(`Wrote ${OUT_PATH} (${rubStarts.length} rub' starts).`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
